-- NetLet health check — generated by Backend/scripts/build-health-check.mjs. Do not edit.
--
-- Is the shop working? Paste the whole file into the Supabase SQL editor and
-- run it. Each row is one check, and the LAST row is the verdict:
--
--   status  ok       nothing to do
--           fail     the shop is broken for shoppers, or money is wrong
--           warn     worth fixing; nothing is broken yet
--           to do    work waiting for somebody in the portal
--           info     a fact, for reference
--           not run  the check could not run — almost always a schema that is
--                    behind; the row says which column or table is missing
--
-- Every row that is not ok says what to do in its last column.
--
-- It changes nothing in the database. The one thing it creates is a temporary
-- function in pg_temp, which belongs to this session and is gone when it ends.
-- docs/schema-audit.sql is its companion: that one says whether every migration
-- landed, this one whether the shop works on top of them.
--
-- 42 checks, 68 tables, 5 departments.

-- (Not "found": inside PL/pgSQL that name is the built-in FOUND flag.)
CREATE OR REPLACE FUNCTION pg_temp.netlet_measure(query text, OUT reading text, OUT flagged boolean, OUT problem text)
LANGUAGE plpgsql AS $measure$
BEGIN
  EXECUTE query INTO reading, flagged;
EXCEPTION WHEN others THEN
  reading := NULL;
  flagged := NULL;
  problem := SQLERRM;
END
$measure$;

WITH
checks (position, area, name, kind, query, advice) AS (VALUES
  (1, 'Database', 'Postgres version', 'info',
   $q$SELECT split_part(version(), ' on ', 1), false$q$,
   ''),
  (2, 'Database', 'Database size', 'info',
   $q$SELECT pg_size_pretty(pg_database_size(current_database())), false$q$,
   ''),
  (3, 'Database', 'Photos and seller documents stored', 'info',
   $q$SELECT pg_size_pretty(coalesce((SELECT sum(byte_size) FROM media_files), 0) + coalesce((SELECT sum(byte_size) FROM application_documents), 0)) || ' — ' || (SELECT count(*) FROM media_files) || ' photos, ' || (SELECT count(*) FROM application_documents) || ' documents', false$q$,
   ''),
  (4, 'Database', 'Connections in use', 'warn',
   $q$SELECT count(*) || ' of ' || current_setting('max_connections'), count(*) > 0.8 * current_setting('max_connections')::int FROM pg_stat_activity$q$,
   'Nearly every connection is taken. DATABASE_URL in Vercel should be Supabase''s Transaction pooler (port 6543), not the direct connection: see docs/SUPABASE.md.'),
  (5, 'Database', 'Sessions stuck inside a transaction', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM pg_stat_activity WHERE state LIKE 'idle in transaction%' AND state_change < now() - interval '5 minutes'$q$,
   'They hold locks that make other writes, and the bootstrap, wait. End each with SELECT pg_terminate_backend(pid) on its row of pg_stat_activity.'),
  (6, 'Database', 'Queries running over five minutes', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM pg_stat_activity WHERE state = 'active' AND pid <> pg_backend_pid() AND query_start < now() - interval '5 minutes'$q$,
   'Look at them in pg_stat_activity; end one with SELECT pg_cancel_backend(pid).'),
  (7, 'Schema', 'Tables the code expects', 'fail',
   $q$SELECT count(*) FILTER (WHERE to_regclass(format('public.%I', t)) IS NOT NULL) || ' of ' || count(*), bool_or(to_regclass(format('public.%I', t)) IS NULL) FROM unnest(string_to_array('ad_bookings,affiliates,application_documents,audit_log,auth_attempts,bundle_items,bundles,cart_item_addons,cart_items,carts,categories,commission_proposals,courier_members,couriers,customer_addresses,customer_notification_preferences,customer_preferences,damage_claims,delivery_ratings,discount_codes,discount_redemptions,driver_positions,feature_switches,followed_products,fulfilment_centres,fulfilment_charges,gift_card_uses,gift_cards,guides,inbound_lines,inbound_shipments,invoice_counters,invoices,media_files,membership_terms,memberships,notification_deliveries,notifications,order_item_addons,order_items,order_tracking_events,orders,payout_files,payout_run_items,payout_runs,platform_settings,point_entries,price_offers,product_addons,product_images,product_variants,products,referrals,return_requests,reviews,saved_products,staff_grants,stock_movements,subscriptions,support_conversations,support_messages,users,vendor_applications,vendor_members,vendor_warnings,vendors,wishlist_items,wishlists', ',')) t$q$,
   'Run docs/supabase-bootstrap.sql again, in full, then docs/schema-audit.sql for the detail.'),
  (8, 'Schema', 'Tables a later migration removed', 'fail',
   $q$SELECT count(*) FILTER (WHERE to_regclass(format('public.%I', t)) IS NOT NULL)::text, bool_or(to_regclass(format('public.%I', t)) IS NOT NULL) FROM unnest(string_to_array('conversation_messages,conversations', ',')) t$q$,
   'Still here means the newest bootstrap has not run. Run docs/supabase-bootstrap.sql again, in full, then docs/schema-audit.sql for the detail.'),
  (9, 'Shop', 'Departments', 'fail',
   $q$SELECT count(*) || ' of 5', count(*) < 5 FROM categories WHERE slug IN ('electronics', 'home-and-kitchen', 'beauty', 'style', 'grocery')$q$,
   'Run docs/supabase-bootstrap.sql again, in full, then docs/schema-audit.sql for the detail.'),
  (10, 'Shop', 'NetLet''s own store', 'fail',
   $q$SELECT coalesce(max(status::text), 'missing'), coalesce(max(status::text), '') <> 'approved' FROM vendors WHERE slug = 'netlet'$q$,
   'It owns NetLet''s own products and must be approved. Run docs/supabase-bootstrap.sql again, in full, then docs/schema-audit.sql for the detail.'),
  (11, 'Shop', 'Products a shopper can see', 'fail',
   $q$SELECT count(*)::text, count(*) = 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved'$q$,
   'The shop shows nothing. Publish a product at /admin/products, and approve its store at /admin/vendors.'),
  (12, 'Shop', 'Stores with something on sale', 'info',
   $q$SELECT count(DISTINCT v.id)::text, false FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved'$q$,
   ''),
  (13, 'Shop', 'Published products hidden by their store', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status <> 'approved'$q$,
   'Their store is pending or suspended, so shoppers do not see them. Approve the store at /admin/vendors, unless the suspension is meant.'),
  (14, 'Shop', 'Shown products with no variant', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved' AND NOT EXISTS (SELECT 1 FROM product_variants pv WHERE pv.product_id = p.id)$q$,
   'Shoppers see them and cannot buy them. Add a price on the product''s page, or unpublish it.'),
  (15, 'Shop', 'Shown products priced at zero', 'fail',
   $q$SELECT count(DISTINCT p.id)::text, count(*) > 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved' AND EXISTS (SELECT 1 FROM product_variants pv WHERE pv.product_id = p.id AND pv.price <= 0)$q$,
   'These can be bought for nothing. Set a price on the product''s page, or unpublish it.'),
  (16, 'Shop', 'Shown products with no photo', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved' AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id = p.id AND pi.kind = 'image')$q$,
   'Shoppers see a placeholder. Add a photo on the product''s page.'),
  (17, 'Shop', 'Shown products sold out', 'info',
   $q$SELECT count(*)::text, false FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved' AND NOT EXISTS (SELECT 1 FROM product_variants pv WHERE pv.product_id = p.id AND (pv.stock > 0 OR pv.preorder_stock > 0))$q$,
   ''),
  (18, 'Shop', 'Stock below zero', 'fail',
   $q$SELECT count(*)::text, count(*) > 0 FROM product_variants WHERE stock < 0 OR preorder_stock < 0$q$,
   'The stock take is meant to make this impossible. Correct the count at /admin/stock, and tell the developer.'),
  (19, 'Shop', 'Savings hidden for want of a discount permit', 'todo',
   $q$SELECT count(DISTINCT p.id)::text, count(*) > 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved' AND EXISTS (SELECT 1 FROM product_variants pv WHERE pv.product_id = p.id AND pv.compare_at_price > pv.price) AND (nullif(trim(v.discount_licence_number), '') IS NULL OR v.discount_licence_expires_at < now())$q$,
   'These sell at their price with the was-price withheld, as the law requires. Record or renew the store''s discount permit on its page to show the saving.'),
  (20, 'Shop', 'Cash on delivery', 'fail',
   $q$SELECT coalesce((SELECT CASE WHEN enabled THEN 'on' ELSE 'off' END FROM feature_switches WHERE key = 'cashOnDelivery'), 'on'), coalesce((SELECT NOT enabled FROM feature_switches WHERE key = 'cashOnDelivery'), false)$q$,
   'Cash is the only way to pay, so nobody can order. Switch it on at /admin/features.'),
  (21, 'Shop', 'Features an administrator switched off', 'info',
   $q$SELECT coalesce(string_agg(key, ', ' ORDER BY key), 'none'), false FROM feature_switches WHERE NOT enabled$q$,
   ''),
  (22, 'Accounts', 'Administrators', 'fail',
   $q$SELECT count(*)::text, count(*) = 0 FROM users WHERE role = 'admin'$q$,
   'Nobody can open the admin portal. Set OWNER_EMAIL in Vercel and register with that address, or run UPDATE users SET role = ''admin'' WHERE email = ''you@example.com''.'),
  (23, 'Accounts', 'Accounts', 'info',
   $q$SELECT count(*) || ' — ' || count(*) FILTER (WHERE last_signed_in > now() - interval '30 days') || ' signed in this month', false FROM users$q$,
   ''),
  (24, 'Accounts', 'Accounts with two password stores', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM users WHERE supabase_uid IS NOT NULL AND password_hash IS NOT NULL$q$,
   'Exactly one of supabase_uid and password_hash should be set. Tell the developer.'),
  (25, 'Accounts', 'Selling stores without an owner', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM vendors v WHERE v.status = 'approved' AND v.slug <> 'netlet' AND NOT EXISTS (SELECT 1 FROM vendor_members m WHERE m.vendor_id = v.id AND m.role = 'owner')$q$,
   'Nobody runs their team. Add an owner on the store''s page under /admin/vendors.'),
  (26, 'Money', 'Orders', 'info',
   $q$SELECT count(*) || ' — ' || count(*) FILTER (WHERE placed_at > now() - interval '7 days') || ' this week', false FROM orders$q$,
   ''),
  (27, 'Money', 'Order lines that do not add up', 'fail',
   $q$SELECT count(*)::text, count(*) > 0 FROM order_items WHERE commission_amount + vendor_net <> line_total$q$,
   'Commission plus the seller''s share must equal the line, or finance and payouts are wrong for these orders. Tell the developer.'),
  (28, 'Money', 'Selling stores charging no commission', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM vendors v WHERE v.status = 'approved' AND v.slug <> 'netlet' AND v.commission_percent = 0 AND coalesce(v.commission_fixed, 0) = 0$q$,
   'Zero is allowed, but is more often a rate nobody set. Set it on the store''s page if 0% was not meant.'),
  (29, 'Money', 'Stores selling without a payout IBAN', 'warn',
   $q$SELECT count(DISTINCT v.id)::text, count(*) > 0 FROM products p JOIN vendors v ON v.id = p.vendor_id WHERE p.status = 'published' AND v.status = 'approved' AND v.slug <> 'netlet' AND nullif(trim(v.payout_iban), '') IS NULL$q$,
   'Their payouts cannot be prepared. Add the IBAN on the store''s page.'),
  (30, 'Money', 'Payouts prepared, not marked sent', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM payout_runs WHERE status = 'prepared'$q$,
   'Send the bank file, then mark each sent with the bank''s reference at /admin/payouts.'),
  (31, 'Waiting on you', 'Products waiting for review', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM products WHERE status = 'pending_review'$q$,
   '/admin/review'),
  (32, 'Waiting on you', 'Seller applications to decide', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM vendor_applications WHERE status = 'submitted'$q$,
   '/admin/applications'),
  (33, 'Waiting on you', 'Returns waiting for NetLet''s decision', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM return_requests WHERE status = 'review'$q$,
   '/admin/returns'),
  (34, 'Waiting on you', 'Refunds owed to shoppers', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM return_requests WHERE status = 'refunded' AND refund_paid_at IS NULL$q$,
   'The item came back and the money has not: /admin/returns'),
  (35, 'Waiting on you', 'Help conversations waiting for a reply', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM support_conversations WHERE status = 'open'$q$,
   '/admin/support'),
  (36, 'Waiting on you', 'Home banners to approve', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM ad_bookings WHERE banner_status = 'pending' AND cancelled_on IS NULL AND ends_on >= (now() AT TIME ZONE 'Asia/Kuwait')::date$q$,
   '/admin/ads — a day it waits is a day it does not run'),
  (37, 'Waiting on you', 'Commission proposals', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM commission_proposals WHERE status = 'pending'$q$,
   '/admin/commission'),
  (38, 'Waiting on you', 'Damage claims open', 'todo',
   $q$SELECT count(*)::text, count(*) > 0 FROM damage_claims WHERE status = 'open'$q$,
   '/admin/claims'),
  (39, 'Daily jobs', 'Emails that gave up', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM notification_deliveries WHERE status = 'failed'$q$,
   'Check RESEND_API_KEY and NOTIFY_EMAIL_FROM in Vercel; each row''s last_error says why it failed.'),
  (40, 'Daily jobs', 'Emails waiting more than two days', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM notification_deliveries WHERE status = 'pending' AND next_attempt_at < now() - interval '2 days'$q$,
   'The daily job is not running: set CRON_SECRET in Vercel''s environment variables (vercel.json schedules it), then redeploy.'),
  (41, 'Daily jobs', 'Standing orders overdue', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM subscriptions WHERE status = 'active' AND next_run_on < (now() AT TIME ZONE 'Asia/Kuwait')::date - 1$q$,
   'The daily job is not running: set CRON_SECRET in Vercel''s environment variables (vercel.json schedules it), then redeploy.'),
  (42, 'Security', 'Tables the anon key can read', 'warn',
   $q$SELECT count(*)::text, count(*) > 0 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind = 'r' AND NOT c.relrowsecurity AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') AND has_table_privilege('anon', c.oid, 'SELECT')$q$,
   'Row-level security is off on these, so Supabase''s Data API serves them to anybody holding the anon key. docs/SUPABASE-AUTH.md, "One thing to check while you are in the dashboard", has the two ways to close it.')
),
measured AS (
  SELECT c.*, m.reading, m.flagged, m.problem
  FROM checks c CROSS JOIN LATERAL pg_temp.netlet_measure(c.query) m
),
judged AS (
  SELECT position, area, name, reading, advice, problem,
    CASE
      WHEN problem IS NOT NULL THEN 'not run'
      WHEN kind = 'info' THEN 'info'
      WHEN flagged THEN CASE kind WHEN 'todo' THEN 'to do' ELSE kind END
      ELSE 'ok'
    END AS status
  FROM measured
)
SELECT "#", area, "check", result, status, "what to do" FROM (
  SELECT position AS "#", area, name AS "check", coalesce(reading, '') AS result, status,
    CASE
      WHEN problem IS NOT NULL THEN problem || '. Run docs/supabase-bootstrap.sql again, in full, then docs/schema-audit.sql for the detail.'
      WHEN status IN ('fail', 'warn', 'to do') THEN advice
      ELSE ''
    END AS "what to do"
  FROM judged
  UNION ALL
  SELECT 43, 'Result', 'Overall',
    coalesce(nullif(concat_ws(', ',
      nullif(count(*) FILTER (WHERE status = 'fail') || ' failing', '0 failing'),
      nullif(count(*) FILTER (WHERE status = 'not run') || ' not run', '0 not run'),
      nullif(count(*) FILTER (WHERE status = 'warn') || ' to look at', '0 to look at'),
      nullif(count(*) FILTER (WHERE status = 'to do') || ' waiting on you', '0 waiting on you')), ''), 'all clear'),
    CASE
      WHEN count(*) FILTER (WHERE status IN ('fail', 'not run')) > 0 THEN 'fail'
      WHEN count(*) FILTER (WHERE status = 'warn') > 0 THEN 'warn'
      ELSE 'ok'
    END,
    CASE
      WHEN count(*) FILTER (WHERE status IN ('fail', 'not run')) > 0 THEN 'Fix the failing rows first; each says how. Then run this again.'
      WHEN count(*) FILTER (WHERE status = 'warn') > 0 THEN 'The shop works. The warn rows above are worth a look.'
      ELSE 'Healthy: the shop can sell, the money adds up, and nothing is broken.'
    END
  FROM judged
) AS report
ORDER BY "#";
